CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `totalhorascontratadas` AS SELECT `modal`.`mes` AS `mes`, `modal`.`anio` AS `anio`, sum(`modal`.`valor`) AS `horascontratadas`, sum(`modal`.`preciototal`) AS `totalEuros` FROM `modalidadhoras` AS `modal` WHERE `modal`.`modalidad` = 'horas' GROUP BY `modal`.`mes`, `modal`.`anio` ;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `totalhorascontratfijo`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `totalhorascontratfijo` AS SELECT sum(`modalidadcostefijo`.`valor`) AS `totalcontratado`, `modalidadcostefijo`.`mes` AS `mes`, `modalidadcostefijo`.`anio` AS `anio` FROM `modalidadcostefijo` WHERE `modalidadcostefijo`.`modalidad` = 'fijo' GROUP BY `modalidadcostefijo`.`mes`, `modalidadcostefijo`.`anio` ;

